#!/usr/bin/env bash
# skills-hint.sh — print the one-line cp skills hint at session start (#395).
#
# The line is GENERATED by `cxp skills --hint` from each skill's own
# frontmatter (plugin commands, plugin skills, the tenant's .claude/skills/),
# never hand-written here. CLAUDE_PLUGIN_ROOT is inherited, so the engine
# reads THIS plugin's files live rather than the snapshot bundled with cxp.
#
# Silent no-op outside a tenant, when `cxp` is missing, or when it is too old
# to have `skills`. Never fails the session: always exit 0.

set -u

dir="$PWD"
root=""
while [ "$dir" != "/" ] && [ -n "$dir" ]; do
    if [ -f "$dir/.cp-engine.toml" ]; then root="$dir"; break; fi
    dir=$(dirname "$dir")
done
[ -z "$root" ] && exit 0
command -v cxp >/dev/null 2>&1 || exit 0

line="$(cxp skills --hint 2>/dev/null | head -n 1)" || true
[ -n "$line" ] && printf '%s\n' "$line"
exit 0
